using DG.Tweening; using UnityEngine; using UnityEngine.Events;  public class MenuCameraTransition : MonoBehaviour {     [Header("Камера")]     [SerializeField] private Transform _camera;      [Header("Точки")]     [SerializeField] private Transform _startPoint;     [SerializeField] private Transform _targetPoint;      [Header("Анимация")]     [SerializeField] private float _duration = 2f;     [SerializeField] private Ease _ease = Ease.InOutCubic;      [Header("События")]     public UnityEvent OnTransitionComplete;      public void PlayToTarget() => MoveTo(_targetPoint);     public void PlayToStart() => MoveTo(_startPoint);      private void MoveTo(Transform point)     {         if (_camera == null || point == null) return;          DOTween.Kill(_camera);          _camera.DOMove(point.position, _duration).SetEase(_ease);         _camera.DORotateQuaternion(point.rotation, _duration)             .SetEase(_ease)             .OnComplete(() => OnTransitionComplete?.Invoke());     } }